(function(){"use strict";document.addEventListener("click",function(e){const btn=e.target.closest(".ob-follow-btn");if(!btn)return;const card=btn.closest(".ob-person"),chefId=card&&card.getAttribute("data-user-id");if(!chefId)return;const action=btn.getAttribute("data-following")==="1"?"unfollow":"follow";btn.disabled=!0,fetch("api/follow.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({chef_id:parseInt(chefId,10),action})}).then(r=>r.json()).then(data=>{if(data&&data.success){const nowFollowing=action==="follow";btn.setAttribute("data-following",nowFollowing?"1":"0"),btn.textContent=nowFollowing?"Following":"Follow",btn.classList.toggle("is-following",nowFollowing)}}).catch(()=>{}).finally(()=>{btn.disabled=!1})})})();
